use std::env;
use std::fs::File;
use std::io::{self, BufRead, Read, Write};

mod completions;
use completions::*;

#[derive(Debug, PartialEq)]
enum Encoding {
    Utf8Lossy,
    Utf8,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut hscale: f64 = 1.0;
    let mut vscale: f64 = 1.0;
    let mut padding: Option<usize> = None;
    let mut encoding: Encoding = Encoding::Utf8Lossy;
    let mut file: Option<String> = None;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            io::stdout().write_all(HELP_TEXT).unwrap();
            return;
        } else if arg == "--version" {
            println!("code-minimap 0.6.8");
            return;
        } else if arg == "-H" || arg == "--horizontal-scale" {
            i += 1;
            if i < args.len() {
                hscale = args[i].parse().unwrap();
            }
        } else if arg.starts_with("-H") && arg.len() > 2 {
            hscale = arg[2..].parse().unwrap();
        } else if arg.starts_with("--horizontal-scale=") {
            hscale = arg["--horizontal-scale=".len()..].parse().unwrap();
        } else if arg == "-V" || arg == "--vertical-scale" {
            i += 1;
            if i < args.len() {
                vscale = args[i].parse().unwrap();
            }
        } else if arg.starts_with("-V") && arg.len() > 2 {
            vscale = arg[2..].parse().unwrap();
        } else if arg.starts_with("--vertical-scale=") {
            vscale = arg["--vertical-scale=".len()..].parse().unwrap();
        } else if arg == "--padding" {
            i += 1;
            if i < args.len() {
                padding = Some(args[i].parse().unwrap());
            }
        } else if arg.starts_with("--padding=") {
            padding = Some(arg["--padding=".len()..].parse().unwrap());
        } else if arg == "--encoding" {
            i += 1;
            if i < args.len() {
                let enc = &args[i];
                if enc == "utf8" {
                    encoding = Encoding::Utf8;
                } else {
                    encoding = Encoding::Utf8Lossy;
                }
            }
        } else if arg.starts_with("--encoding=") {
            let enc = &arg["--encoding=".len()..];
            if enc == "utf8" {
                encoding = Encoding::Utf8;
            } else {
                encoding = Encoding::Utf8Lossy;
            }
        } else if arg == "completion" {
            i += 1;
            if i < args.len() {
                let shell = &args[i];
                if shell == "bash" { io::stdout().write_all(BASH_COMP).unwrap(); }
                else if shell == "zsh" { io::stdout().write_all(ZSH_COMP).unwrap(); }
                else if shell == "fish" { io::stdout().write_all(FISH_COMP).unwrap(); }
                else if shell == "elvish" { io::stdout().write_all(ELVISH_COMP).unwrap(); }
                else if shell == "powershell" { io::stdout().write_all(POWERSHELL_COMP).unwrap(); }
            }
            return;
        } else if !arg.starts_with("-") || arg == "-" {
            if file.is_none() {
                file = Some(arg.clone());
            }
        }
        i += 1;
    }

    let mut content = Vec::new();
    if let Some(path) = &file {
        if path != "-" {
            let mut f = File::open(path).expect("failed to open file");
            f.read_to_end(&mut content).unwrap();
        } else {
            io::stdin().read_to_end(&mut content).unwrap();
        }
    } else {
        io::stdin().read_to_end(&mut content).unwrap();
    }

    let text = if encoding == Encoding::Utf8 {
        match String::from_utf8(content) {
            Ok(s) => s,
            Err(_) => {
                eprintln!("code-minimap: stream did not contain valid UTF-8");
                std::process::exit(1);
            }
        }
    } else {
        String::from_utf8_lossy(&content).into_owned()
    };

    // Remove trailing newline if any, because lines() ignores it, but split('\n') would add an empty line.
    let lines: Vec<&str> = text.split('\n').collect();
    let mut actual_lines = lines.clone();
    if actual_lines.last() == Some(&"") {
        actual_lines.pop();
    }
    if actual_lines.is_empty() {
        return;
    }

    let total_lines = actual_lines.len();
    let max_y_braille = ((total_lines - 1) as f64 * vscale).floor() as usize / 4;

    let mut braille_lines: Vec<Vec<u8>> = vec![vec![0; 0]; max_y_braille + 1];

    let mut stdout = io::stdout().lock();

    for y in 0..total_lines {
        let line = actual_lines[y];
        let first = line.char_indices().find(|(_, c)| !c.is_whitespace()).map(|(i, _)| i);
        let last = line.char_indices().rev().find(|(_, c)| !c.is_whitespace()).map(|(i, _)| i);

        if let (Some(f), Some(l)) = (first, last) {
            let min_x = (f as f64 * hscale).round() as isize;
            let max_x = ((l + 1) as f64 * hscale).floor() as isize - 1;
            let max_x = std::cmp::max(min_x, max_x);
            let y_mapped = (y as f64 * vscale).floor() as usize;

            let y_braille = y_mapped / 4;
            let dot_y = y_mapped % 4;

            if y_braille > max_y_braille {
                continue; // Should not happen
            }

            for x in min_x..=max_x {
                let x = x as usize;
                let braille_x = x / 2;
                let dot_x = x % 2;

                while braille_lines[y_braille].len() <= braille_x {
                    braille_lines[y_braille].push(0);
                }

                let mask = match (dot_x, dot_y) {
                    (0, 0) => 0x01,
                    (0, 1) => 0x02,
                    (0, 2) => 0x04,
                    (0, 3) => 0x40,
                    (1, 0) => 0x08,
                    (1, 1) => 0x10,
                    (1, 2) => 0x20,
                    (1, 3) => 0x80,
                    _ => 0,
                };
                braille_lines[y_braille][braille_x] |= mask;
            }
        }
    }

    for line in braille_lines {
        let len = line.len();
        let mut chars = len;
        if len == 0 {
            chars = 1;
        }

        for i in 0..len {
            let val = line[i];
            let code = 0x2800 | (val as u32);
            let c = std::char::from_u32(code).unwrap();
            write!(stdout, "{}", c).unwrap();
        }
        if len == 0 {
            write!(stdout, "{}", '\u{2800}').unwrap();
        }

        if let Some(p) = padding {
            if chars < p {
                for _ in 0..(p - chars) {
                    write!(stdout, " ").unwrap();
                }
            }
        }
        writeln!(stdout).unwrap();
    }
}
